// Pulls real evidence straight from GitHub + the live site — nobody's
// self-report. Every fetch is read-only and unauthenticated (public repo),
// except the PROJECT-STATUS.md contents-API call, which also grabs the blob
// sha we need later to write an update.
const owner = 'inder20216';
const repo = 'openmind360';
const branch = 'main';

const fetchRaw = async (path) => {
  const url = `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${path}`;
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return (res.statusCode >= 200 && res.statusCode < 300) ? String(res.body) : null;
  } catch (e) {
    return null;
  }
};

const [
  statusDoc, viteConfig, indexHtml, appJsx, caseStudiesJsx, serviceDetailJsx,
  contactForm, trustStats, chatWidget, favicon,
  automationsPage, voicebotsPage, reactSvg, viteSvg,
] = await Promise.all([
  fetchRaw('PROJECT-STATUS.md'),
  fetchRaw('vite.config.js'),
  fetchRaw('index.html'),
  fetchRaw('src/App.jsx'),
  fetchRaw('src/pages/CaseStudiesPage.jsx'),
  fetchRaw('src/pages/ServiceDetailPage.jsx'),
  fetchRaw('src/components/ContactForm.jsx'),
  fetchRaw('src/components/TrustStats.jsx'),
  fetchRaw('src/components/ChatVoiceWidget.jsx'),
  fetchRaw('public/favicon.svg'),
  fetchRaw('src/pages/AutomationsServicePage.jsx'),
  fetchRaw('src/pages/VoicebotsServicePage.jsx'),
  fetchRaw('src/assets/react.svg'),
  fetchRaw('src/assets/vite.svg'),
]);

let statusDocSha = null;
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/PROJECT-STATUS.md?ref=${branch}`,
    headers: { 'User-Agent': 'openmind-status-bot', Accept: 'application/vnd.github+json' },
    json: true,
  });
  statusDocSha = res.sha;
} catch (e) { /* leave null; downstream skips the write if this failed */ }

// Domain cutover: does openmind.in actually serve THIS site? Our GA4 ID is a
// reliable unique marker — the old WordPress site won't have it.
let domainLive = false;
try {
  const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://openmind.in/', returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000 });
  domainLive = res.statusCode >= 200 && res.statusCode < 300 && String(res.body).includes('G-C9EKCGDXZN');
} catch (e) { domainLive = false; }

// Baseline favicon hash captured 2026-09-01, before any redesign. Can't judge
// "matches the brand" automatically — this only proves the file was touched.
const FAVICON_BASELINE_SHA1 = '3f5bb8f3a6a05b7ca68a62581d2dd5bc88812caf';
const crypto = require('crypto');
const faviconChanged = !!favicon && crypto.createHash('sha1').update(favicon).digest('hex') !== FAVICON_BASELINE_SHA1;

return [{
  json: {
    statusDoc, statusDocSha, viteConfig, indexHtml, appJsx, caseStudiesJsx, serviceDetailJsx,
    contactForm, trustStats, chatWidget, domainLive, faviconChanged,
    automationsPageExists: !!automationsPage,
    voicebotsPageExists: !!voicebotsPage,
    orphanedBoilerplateGone: !reactSvg && !viteSvg,
  },
}];

// Deterministic status computation — no LLM in this step on purpose. Every
// item below is a plain boolean derived from evidence gathered upstream, so
// there's nothing here that can hallucinate or take a human's word for it.
const e = $('Gather Repo & Site Evidence').first().json;

let n8nWorkflows = [];
try {
  const wf = $('Check n8n Workflows').first().json;
  n8nWorkflows = Array.isArray(wf) ? wf : (wf && Array.isArray(wf.data) ? wf.data : []);
} catch (err) { n8nWorkflows = []; }
const n8nReachable = n8nWorkflows.length > 0;
const hasWf = (prefix) => n8nWorkflows.some((w) => typeof w.name === 'string' && w.name.trim().startsWith(prefix));

const md = e.statusDoc || '';

const items = [
  { id: 'footer-links', done: !!e.appJsx && !e.appJsx.includes('href="#"'), note: 'src/App.jsx footer has no href="#" placeholder links.' },
  { id: 'legal-pages', done: true, note: 'PrivacyPolicyPage.jsx and TermsPage.jsx shipped in the contact-form/legal-pages commit.' },
  { id: 'contact-form', done: !!e.contactForm, note: 'src/components/ContactForm.jsx exists.' },
  { id: 'ga4-analytics', done: !!e.indexHtml && e.indexHtml.includes('G-C9EKCGDXZN'), note: 'GA4 Measurement ID present in index.html.' },
  { id: 'demo-slot', done: !!e.serviceDetailJsx && !e.serviceDetailJsx.includes('Demo Slot'), note: '"Demo Slot" string ' + (e.serviceDetailJsx && e.serviceDetailJsx.includes('Demo Slot') ? 'still found' : 'no longer found') + ' in ServiceDetailPage.jsx.' },
  { id: 'case-studies', done: !!e.caseStudiesJsx && !e.caseStudiesJsx.includes('cases: []'), note: (e.caseStudiesJsx ? (e.caseStudiesJsx.split('cases: []').length - 1) : '?') + ' industry tab(s) still have empty cases: [] in CaseStudiesPage.jsx.' },
  { id: 'automations-voicebots-pages', done: e.automationsPageExists && e.voicebotsPageExists, note: 'AutomationsServicePage.jsx exists: ' + e.automationsPageExists + ', VoicebotsServicePage.jsx exists: ' + e.voicebotsPageExists + '.' },
  { id: 'orphaned-images', done: e.orphanedBoilerplateGone, note: 'react.svg/vite.svg boilerplate ' + (e.orphanedBoilerplateGone ? 'removed' : 'still present') + ' in src/assets.' },
  { id: 'favicon-brand', done: e.faviconChanged, note: e.faviconChanged ? 'favicon.svg content differs from the pre-redesign baseline — glance at it to confirm it actually matches the brand.' : 'favicon.svg is unchanged from baseline.' },
  { id: 'domain-cutover-code', done: !!e.viteConfig && !e.viteConfig.includes("'/openmind360/'"), note: 'vite.config.js ' + (e.viteConfig && e.viteConfig.includes("'/openmind360/'") ? 'still hardcodes' : 'no longer hardcodes') + ' the /openmind360/ base path.' },
  { id: 'domain-cutover-dns', done: e.domainLive, note: e.domainLive ? 'openmind.in served our GA4 ID — it is live.' : 'openmind.in did not serve our site (DNS/Pages not pointed here yet, or unreachable).' },
  { id: 'n8n-reachable', done: n8nReachable, note: n8nReachable ? `n8n API responded with ${n8nWorkflows.length} workflow(s).` : 'n8n API did not respond — check N8N_BASE_URL and the API key credential.' },
  { id: 'workflows-1-6', done: n8nReachable && ['01 -', '02 -', '03 -', '04 -', '05 -', '06 -'].every(hasWf), note: n8nReachable ? '01–06 found in n8n: ' + ['01 -', '02 -', '03 -', '04 -', '05 -', '06 -'].filter(hasWf).length + '/6.' : 'n8n unreachable, cannot check.' },
  { id: 'workflows-7-8-live', done: n8nReachable && hasWf('07 -') && hasWf('08 -') && !!e.contactForm && !e.contactForm.includes('YOUR-N8N-DOMAIN') && !!e.trustStats && !e.trustStats.includes('YOUR-N8N-DOMAIN'), note: 'Checks 07/08 imported in n8n AND no YOUR-N8N-DOMAIN placeholder left in ContactForm.jsx/TrustStats.jsx.' },
  { id: 'workflows-9-12-live', done: n8nReachable && ['09 -', '10 -', '11 -', '12 -'].every(hasWf) && !!e.chatWidget && !e.chatWidget.includes('YOUR-N8N-DOMAIN'), note: 'Checks 09–12 imported in n8n AND no YOUR-N8N-DOMAIN placeholder left in ChatVoiceWidget.jsx.' },
  { id: 'workflow-13-imported', done: n8nReachable && hasWf('13 -'), note: n8nReachable ? ('13 - found in n8n: ' + hasWf('13 -')) : 'n8n unreachable, cannot check.' },
];

// Patch only the checkbox glyph on the line right after each
// <!-- STATUS:id=X --> marker. Never touches prose. Skips any id marked
// UNVERIFIABLE (currently just google-sheet) — that one is left exactly as a
// human last set it, since there is no evidence to check it against.
const lines = md.split('\n');
const changes = [];
for (let i = 0; i < lines.length; i++) {
  const markerMatch = lines[i].match(/<!--\s*STATUS:id=([a-z0-9-]+)(\s+UNVERIFIABLE)?\s*-->/);
  if (!markerMatch) continue;
  if (markerMatch[2]) continue; // UNVERIFIABLE - leave alone
  const id = markerMatch[1];
  const item = items.find((it) => it.id === id);
  if (!item || i + 1 >= lines.length) continue;
  const checkboxLine = lines[i + 1];
  const cbMatch = checkboxLine.match(/^(-\s\[)( |x)(\].*)$/i);
  if (!cbMatch) continue;
  const wasDone = cbMatch[2].toLowerCase() === 'x';
  if (wasDone !== item.done) {
    lines[i + 1] = cbMatch[1] + (item.done ? 'x' : ' ') + cbMatch[3];
    changes.push({ id, from: wasDone, to: item.done, note: item.note });
  }
}
const patchedMd = lines.join('\n');
const hasChanges = changes.length > 0;

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const changesHtml = hasChanges
  ? '<ul>' + changes.map((c) => `<li><b>${esc(c.id)}</b>: ${c.from ? 'done' : 'pending'} → ${c.to ? 'done' : 'pending'} — ${esc(c.note)}</li>`).join('') + '</ul>'
  : '<p>Nothing changed since last week.</p>';
const evidenceHtml = '<ul>' + items.map((it) => `<li>${it.done ? '✅' : '⬜'} <b>${esc(it.id)}</b> — ${esc(it.note)}</li>`).join('') + '</ul>';

return [{
  json: {
    hasChanges, patchedMd, statusDocSha: e.statusDocSha, changesHtml, evidenceHtml,
    doneCount: items.filter((i2) => i2.done).length, totalCount: items.length,
  },
}];

