const status = $('Compute Status From Evidence').first().json;
const pr = $('Create Pull Request').first().json;
const html = `
<h2>Openmind Project — Weekly Status</h2>
<p>${status.doneCount} of ${status.totalCount} auto-tracked items done. This is computed from real repo/n8n/DNS evidence, not self-reported.</p>
<h2>Changed This Week</h2>
${status.changesHtml}
<p>Review and merge: <a href="${pr.html_url}">${pr.html_url}</a></p>
<h2>Full Status</h2>
${status.evidenceHtml}
`;
return [{ json: { html, subject: `Openmind Project — Weekly Status, changes found (${new Date().toLocaleDateString('en-IN')})` } }];

const status = $('Compute Status From Evidence').first().json;
const html = `
<h2>Openmind Project — Weekly Status</h2>
<p>${status.doneCount} of ${status.totalCount} auto-tracked items done. Nothing changed since last week — no PR needed.</p>
<h2>Full Status</h2>
${status.evidenceHtml}
`;
return [{ json: { html, subject: `Openmind Project — Weekly Status, no change (${new Date().toLocaleDateString('en-IN')})` } }];
